#include <dht.h>
dht DHT;
#define DHT11_PIN 2

void setup() {
  Serial.begin(9600);
}

void loop() {
  int chk = DHT.read11(DHT11_PIN);
  Serial.print("Temp: ");
  Serial.print(DHT.temperature);
  Serial.print("C | Humidity: ");
  Serial.print(DHT.humidity);
  Serial.println("%");
  delay(2000);
}
